name: scan-agentic-app-perf
required_skills:
  - scan-agentic-app-perf

scenarios:
  - name: clean-project-zero-criticals
    timeout: 360
    prompt: |
      Audit the agentic .NET app at ./fixture for perf, cost, and reliability issues.
      Read-only — don't edit any source files.
    setup:
      files:
        - path: fixture/MyApp.AppHost/Program.cs
          content: |
            var builder = DistributedApplication.CreateBuilder(args);
            var openai = builder.AddConnectionString("openai");
            builder.AddProject<Projects.MyApp_Coach>("coach")
                   .WithReference(openai)
                   .WaitFor(openai);
            builder.Build().Run();
        - path: fixture/MyApp.Coach/Program.cs
          content: |
            var builder = WebApplication.CreateBuilder(args);
            builder.AddServiceDefaults();
            builder.AddAzureOpenAIClient("openai");
            builder.Services.AddSingleton<IChatClient>(sp =>
                sp.GetRequiredService<AzureOpenAIClient>()
                  .GetChatClient(builder.Configuration["Model"])
                  .AsIChatClient());
            builder.Services.AddSingleton(sp => new ChatClientAgent(
                sp.GetRequiredService<IChatClient>(),
                instructions: "You are a concise coach."));
            var app = builder.Build();
            app.MapDefaultEndpoints();
            app.MapPost("/chat", async (ChatClientAgent agent, string message) =>
                await agent.RunAsync(message));
            app.Run();
        - path: fixture/MyApp.Coach/appsettings.json
          content: |
            { "Model": "gpt-4o-mini" }
    assertions:
      - type: file_exists
        path: fixture/.copilot/perf-reports/scan.md
      - type: file_contains
        path: fixture/.copilot/perf-reports/scan.md
        value: "## Findings"
      - type: file_contains
        path: fixture/.copilot/perf-reports/scan.md
        value: "critical: 0"

  - name: sprawl-fixture-flags-topology
    timeout: 360
    prompt: |
      My agent app at ./fixture feels too complex. Find the perf and topology issues.
    setup:
      files:
        - path: fixture/Sprawl.AppHost/Program.cs
          content: |
            var builder = DistributedApplication.CreateBuilder(args);
            builder.AddProject<Projects.Agent_A>("a");
            builder.AddProject<Projects.Agent_B>("b");
            builder.AddProject<Projects.Agent_C>("c");
            builder.AddProject<Projects.Agent_D>("d");
            builder.AddProject<Projects.Agent_E>("e");
            builder.AddProject<Projects.Agent_F>("f");
            builder.Build().Run();
        - path: fixture/Agent.A/Program.cs
          content: |
            var agent = new ChatClientAgent(client, instructions: "router");
            agent.AddHandoff("b"); agent.AddHandoff("c");
        - path: fixture/Agent.B/Program.cs
          content: |
            var agent = new ChatClientAgent(client, instructions: "router");
            agent.AddHandoff("c"); agent.AddHandoff("d");
    assertions:
      - type: file_exists
        path: fixture/.copilot/perf-reports/scan.md
      - type: file_contains
        path: fixture/.copilot/perf-reports/scan.md
        value: "topology"
      - type: output_contains
        value: "critical"

  - name: full-history-fixture-flags-message-history
    timeout: 360
    prompt: |
      Why is the agent app at ./fixture slow on multi-turn conversations? Find the perf issues.
    setup:
      files:
        - path: fixture/HistoryHog.AppHost/Program.cs
          content: |
            var builder = DistributedApplication.CreateBuilder(args);
            builder.AddProject<Projects.Coach>("coach");
            builder.AddProject<Projects.Critic>("critic");
            builder.Build().Run();
        - path: fixture/Coach/Program.cs
          content: |
            await critic.RunAsync(history, cancellationToken);
    assertions:
      - type: file_contains
        path: fixture/.copilot/perf-reports/scan.md
        value: "history"

  - name: prompt-bloat-fixture-flags-prompt-weight
    timeout: 360
    prompt: |
      Audit the agent app at ./fixture for perf and cost issues.
    setup:
      files:
        - path: fixture/PromptHog.AppHost/Program.cs
          content: |
            var agent = new ChatClientAgent(client, instructions: HUGE_PROMPT);
        - path: fixture/PromptHog.AppHost/HugePrompt.cs
          content: |
            const string HUGE_PROMPT = @"...PLACEHOLDER 12000 CHARS OF RULES AND EXAMPLES...";
    assertions:
      - type: file_contains
        path: fixture/.copilot/perf-reports/scan.md
        value: "prompt"

  - name: missing-otel-fixture-flags-otel-coverage
    timeout: 360
    prompt: |
      Find the observability and perf issues in the agent app at ./fixture.
    setup:
      files:
        - path: fixture/NoOtel.AppHost/Program.cs
          content: |
            var builder = DistributedApplication.CreateBuilder(args);
            builder.AddProject<Projects.Coach>("coach");
            builder.Build().Run();
    assertions:
      - type: file_contains
        path: fixture/.copilot/perf-reports/scan.md
        value: "otel"

  - name: same-model-fixture-flags-model-assignment
    timeout: 360
    prompt: |
      Audit the agentic .NET app at ./fixture for perf and cost issues.
    setup:
      files:
        - path: fixture/MyApp.slnx
          content: |
            <Solution>
              <Project Path="MyApp.AppHost/MyApp.AppHost.csproj" />
            </Solution>
        - path: fixture/MyApp.AppHost/MyApp.AppHost.csproj
          content: |
            <Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><TargetFramework>net10.0</TargetFramework></PropertyGroup></Project>
        - path: fixture/MyApp.AppHost/AppHost.cs
          content: |
            var builder = DistributedApplication.CreateBuilder(args);
            var chat = builder.AddAzureOpenAIChatClient("chat", "gpt-4o-mini");
            builder.AddProject<Projects.Planner>("planner").WithReference(chat);
            builder.AddProject<Projects.Writer>("writer").WithReference(chat);
            builder.AddProject<Projects.Reviewer>("reviewer").WithReference(chat);
            builder.Build().Run();
        - path: fixture/Planner/Program.cs
          content: |
            var builder = WebApplication.CreateBuilder(args);
            builder.AddServiceDefaults();
            builder.Services.AddSingleton(sp => new ChatClientAgent(
                sp.GetRequiredService<IChatClient>(),
                instructions: "You decompose tasks into steps."));
            var app = builder.Build();
            app.Run();
        - path: fixture/Writer/Program.cs
          content: |
            var builder = WebApplication.CreateBuilder(args);
            builder.AddServiceDefaults();
            builder.Services.AddSingleton(sp => new ChatClientAgent(
                sp.GetRequiredService<IChatClient>(),
                instructions: "You write content based on plans."));
            var app = builder.Build();
            app.Run();
        - path: fixture/Reviewer/Program.cs
          content: |
            var builder = WebApplication.CreateBuilder(args);
            builder.AddServiceDefaults();
            builder.Services.AddSingleton(sp => new ChatClientAgent(
                sp.GetRequiredService<IChatClient>(),
                instructions: "You review and approve content."));
            var app = builder.Build();
            app.Run();
    assertions:
      - type: file_exists
        path: fixture/.copilot/perf-reports/scan.md
      - type: file_contains
        path: fixture/.copilot/perf-reports/scan.md
        value: "model"
      - type: output_contains
        value: "model"

  - name: sequential-calls-fixture-flags-parallelism
    timeout: 360
    prompt: |
      Scan the agentic app at ./fixture for perf issues. Focus on whether it could be faster.
    setup:
      files:
        - path: fixture/MyApp.AppHost/Program.cs
          content: |
            var builder = DistributedApplication.CreateBuilder(args);
            builder.AddProject<Projects.Orchestrator>("orchestrator");
            builder.Build().Run();
        - path: fixture/Orchestrator/Program.cs
          content: |
            var builder = WebApplication.CreateBuilder(args);
            builder.AddServiceDefaults();
            builder.AddAzureOpenAIClient("openai");
            builder.Services.AddSingleton<IChatClient>(sp =>
                sp.GetRequiredService<AzureOpenAIClient>()
                  .GetChatClient("gpt-4o-mini")
                  .AsIChatClient());
            var app = builder.Build();
            app.MapPost("/run", async (IChatClient client) =>
            {
                var summary = await client.GetResponseAsync("Summarize the document");
                var translation = await client.GetResponseAsync("Translate the document");
                var keywords = await client.GetResponseAsync("Extract keywords");
                return new { summary, translation, keywords };
            });
            app.Run();
    assertions:
      - type: file_exists
        path: fixture/.copilot/perf-reports/scan.md
      - type: file_contains
        path: fixture/.copilot/perf-reports/scan.md
        value: "parallel"
      - type: output_contains
        value: "parallel"
